function header(title,description,icon='✦',kicker='JEJAK KEBIJAKSANAAN'){return `<div class="page-head"><div><div class="kicker">${kicker}</div><h1 class="page-title">${title}</h1>${description?`<p>${description}</p>`:''}</div><div class="page-mark" aria-hidden="true">${icon}</div></div>`;}
function surface(content, extra=''){app.innerHTML=`<section class="surface ${extra}">${content}</section>`;}
function render(){extraNav.classList.toggle('hidden',!visitedMap);if(current==='home')renderHome();else if(current==='konsep')renderConcept();else if(current==='intro')renderIntro();else if(current==='peta')renderMap();else if(current==='penyusun')renderMembers();else if(current==='petunjuk')renderInstructions();else if(current==='level')renderLesson();else if(current==='infografis')renderInfographic();else if(current==='aktivitas')renderActivity();else if(current==='kuis')renderQuiz();else if(current==='hasil')renderResult();else if(current==='pembahasan')renderReview();else if(current==='refleksi')renderReflection();else if(current==='refleksi-selesai')renderReflectionDone();else if(current==='pustaka')renderSources();else if(current==='kesimpulan')renderConclusion();}
function renderHome(){surface(`${header('Selamat datang, penjelajah!','Jelajahi Darsana dan temukan cara pandang yang beragam tentang realitas.','🌿','EKSPEDISI SAD DARSANA')}<section class="home-concept"><div class="concept-banner"><span>📖</span><div><div class="kicker">MULAI DARI SINI</div><h2>Konsep Utama</h2><p>Kenali pengertian Darsana, kelompok Astika dan Nastika, serta latar pemikiran filsafat India.</p></div><button class="primary" onclick="go('konsep')">Baca konsep →</button></div><div class="home-six-grid">${lessons.map((l,i)=>{const open=i===0||completed.has(i-1);return `<button class="home-darsana-tile tone-${i%6} ${open?'':'tile-locked'}" ${open?'':'disabled'} onclick="openLesson(${i})"><span>${open?l.icon:'🔒'}</span><strong>${l.name}</strong><small>${open?l.focus.split('.')[0]:'Selesaikan materi sebelumnya'}</small></button>`}).join('')}</div><div class="home-activity-strip"><div><span class="activity-emblem">🗝️</span><div><strong>Aktivitas Interaktif: Labirin Kebijaksanaan</strong><p>Buka pintu dengan menjawab soal, kumpulkan kunci, dan jaga nyawamu!</p></div></div><button class="primary" onclick="startActivity()">Masuk labirin →</button></div></section><div class="home-note-grid"><article class="home-note"><strong>🧭 Catatan ekspedisi</strong><p>Materi harus diselesaikan secara berurutan. Aktivitas interaktif dan kuis akhir dapat dikerjakan kapan saja.</p></article><article class="home-note"><strong>🎯 Tujuan pembelajaran</strong><p>Menjelaskan pengertian dan tujuan Darsana, mengidentifikasi enam aliran Sad Darsana, serta menghubungkan pemikirannya dengan kehidupan sehari-hari.</p></article></div><div class="actions"><button class="secondary" onclick="go('petunjuk')">Petunjuk penggunaan</button><button class="primary" onclick="go('intro')">Mulai perjalanan →</button></div>`);}
function renderConcept(){surface(`${header('Konsep Utama','Darsana dalam tradisi intelektual India dan kelompok filsafat India.','📖','MATERI SAD DARSANA')}<article class="concept-reading"><h2>1. Konsep Utama</h2><p>Dalam tradisi intelektual India Darsana merupakan padanan yang paling mendekati istilah filsafat, namun secara esensial ada perbedaan yang sangat mendasar, filsafat (barat) terlepas dari agama sedangkan darsana tetap mengakar pada agama Hindu. Kata darsana berasal dari urat kata <strong>‘drs’</strong> yang berarti melihat (ke dalam) atau mengalami, menjadikan kata darsana yang artinya penglihatan atau pandangan tentang realitas.</p><p>Secara umum filsafat India dibedakan menjadi dua kelompok, yaitu:</p><div class="concept-compare"><section><div class="concept-label">01 · ASTIKA</div><h3>Pandangan Orthodox</h3><p>Pandangan yang orthodox, disebut juga Astika, kelompok ini secara langsung maupun tidak langsung mengakui otoritas Weda sebagai sumber ajarannya. Terdiri dari 6 aliran filsafat (Sad Darsana) yang pada akhirnya disebut sebagai filsafat Hindu, terdiri dari: Nyaya, Vaisesika, Samkhya, Yoga, Purwwa Mimamsa, Wedanta (Uttara Mimamsa).</p><div class="concept-pills">${['Nyaya','Vaisesika','Samkhya','Yoga','Purwwa Mimamsa','Wedanta'].map((n,i)=>`<span>${n}</span>`).join('')}</div></section><section><div class="concept-label">02 · NASTIKA</div><h3>Pandangan Heterodox</h3><p>Pandangan yang heterodox, disebut juga Nastika, kelompok ini tidak mengakui otoritas Weda sebagai sumber ajarannya. Terdiri dari Carwaka, Jaina, dan Buddha.</p><div class="concept-pills concept-pills-alt"><span>Carwaka</span><span>Jaina</span><span>Buddha</span></div></section></div><section class="concept-detail"><h3>Filsafat Carwaka</h3><p>Filsafat carwaka didirikan oleh Brhaspati yang ajarannya tertuang dalam Brhaspati sutra. Carwaka juga berarti seorang materialis yang mempercayai manusia terbentuk dari materi, dan tidak mempercayai adanya atman dan Tuhan, bentuk inilah yang menyebabkan ia sering dianggap sebagai hedonisme timur.</p></section><section class="concept-detail"><h3>Filsafat Jaina</h3><p>Filsafat jaina merupakan sistem filsafat yang mengembangkan tradisi atheisme namun spiritual.</p></section><section class="concept-detail"><h3>Filsafat Buddha</h3><p>Filsafat Buddha lahir dari ajaran-ajaran Buddha Gautama (567 sm) ajarannya bersifat atheisme dan spiritual. Buddha menekankan pada etika, cinta kasih, persaudaraan, menolak sistem kasta, dan menolak otoritas Weda dan pelaksanaan yajna. Tujuan akhir perjalanan hidup manusia adalah nirwana.</p></section></article><div class="actions"><button class="secondary" onclick="go('home')">← Kembali ke beranda</button><button class="primary" onclick="go('peta')">Jelajahi materi Sad Darsana →</button></div>`);}

function renderIntro(){const chats=[`Halo! Aku teman belajarmu. 🌿 Pernahkah kamu bertanya-tanya tentang hakikat kehidupan dan kebenaran?`,`Dalam agama Hindu, kita mengenal Darsana, dari kata <em>dṛś</em> yang berarti “melihat” atau “memandang”. Darsana membantu kita memahami hakikat kehidupan dan kebenaran melalui pemikiran filosofis.`,`Ada enam aliran yang akan kita jelajahi: Nyaya, Waiśesika, Samkhya, Yoga, Mimamsa, dan Wedanta. Setiap aliran menawarkan cara pandang yang menarik.`,`Siap memulai petualangan? Ikuti peta, pelajari setiap tempat, dan temukan bagaimana gagasan Darsana dapat dihubungkan dengan kehidupan sehari-hari.`];surface(`<div class="student-layout"><div class="student-portrait" aria-label="Ilustrasi siswa teman belajar"><span class="student-spark spark-one">✦</span><span class="student-emoji">🧑🏽‍🎓</span><span class="student-spark spark-two">✧</span><span class="student-leaf">❧</span></div><div><div class="speech-label">TEMAN BELAJAR MENYAPA</div><button class="bubble bubble-click" onclick="nextIntro()" aria-label="Klik bubble untuk melanjutkan percakapan">${chats[introStep]}<span class="bubble-hint">${introStep<chats.length-1?'Klik percakapan untuk melanjutkan ↗':'Percakapan selesai · klik tombol di bawah'}</span></button><div class="step-meta">Percakapan ${introStep+1} dari ${chats.length} · Klik bubble untuk melanjutkan</div>${introStep===chats.length-1?`<div class="actions"><button class="primary" onclick="enterMap()">Jelajah peta <span aria-hidden="true">↗</span></button></div>`:''}</div></div>`);}
function renderMap(){const done=completed.size===lessons.length;surface(`${header('Peta penjelajahan','Ikuti jalur belajar untuk mengenal enam aliran Sad Darsana. Selesaikan materi beserta tiga pertanyaan umpan balik untuk membuka langkah berikutnya.','⌁','PETA BELAJAR')}${showObjective?`<button class="map-objective-bubble" onclick="dismissObjective()"><span class="mini-mark">✦</span><span><strong>Tujuan pembelajaran</strong><span>Menjelaskan pengertian dan tujuan Darsana, mengidentifikasi enam aliran Sad Darsana, serta menghubungkan gagasannya dengan kehidupan sehari-hari.</span><small>Klik untuk menutup</small></span></button>`:''}${done?`<div class="map-intro"><span class="mini-mark">🌟</span><div><strong>Selamat, semua materi sudah selesai!</strong><p>Kamu telah menyelesaikan keenam aliran Sad Darsana. Sekarang, jelajahi infografis, aktivitas interaktif, kuis akhir, refleksi, dan daftar pustaka melalui ikon di bagian atas.</p></div></div>`:''}<div class="map-grid">${lessons.map((l,i)=>{const open=i===0||completed.has(i-1);return `<button class="level ${open?'open':''}" ${open?'':'disabled'} onclick="openLesson(${i})"><div class="level-top"><span class="level-icon">${open?l.icon:'🔒'}</span><span class="level-index">TEMPAT ${String(i+1).padStart(2,'0')}</span></div><strong>${l.name}</strong><small>${l.focus}</small><span class="level-status">${completed.has(i)?'✓ Selesai':open?'Mulai belajar →':'Terkunci · selesaikan sebelumnya'}</span></button>`}).join('')}</div><div class="map-progress"><span>${completed.size} dari ${lessons.length} materi selesai</span><div class="progress-track"><span style="width:${completed.size/lessons.length*100}%"></span></div></div><div class="map-feature-actions"><button class="secondary" onclick="startActivity()">🗝️ Aktivitas interaktif: Labirin</button><button class="primary" onclick="startQuiz()">Mulai kuis akhir →</button>${done?`<button class="secondary" onclick="go('kesimpulan')">Baca kesimpulan</button>`:''}</div>`);}
function renderLesson(){const l=lessons[activeLesson],answers=lessonAnswers[activeLesson]||{},done=Object.keys(answers).length===l.feedback.length;const feedbackContent=l.feedback.map((q,i)=>{const answered=answers[i]!==undefined;return `<div class="mini-question"><div class="mini-q-meta">UMPAN BALIK ${i+1} DARI ${l.feedback.length}</div><h3>${q.q}</h3><div class="quiz-options">${q.o.map((o,j)=>`<button class="option ${answered&&j===q.a?'correct':''} ${answered&&answers[i]===j&&j!==q.a?'wrong':''}" onclick="answerLesson(${i},${j})">${String.fromCharCode(65+j)}. ${o}</button>`).join('')}</div>${answered?`<div class="feedback ${answers[i]===q.a?'':'bad'}"><strong>${answers[i]===q.a?'Tepat!':'Belum tepat.'}</strong> ${q.e}</div>`:''}</div>`}).join('');surface(`${header(l.name,l.focus,l.icon,`MATERI ${activeLesson+1} DARI ${lessons.length}`)}<div class="lesson-detail-grid"><article class="lesson-main lesson-content"><div class="lesson-tag">TOKOH · ${l.figure}</div><h2>Mengenal ${l.name}</h2><p>${l.intro}</p>${l.sections.map((s,i)=>`<section class="lesson-section"><h3><span>${String(i+1).padStart(2,'0')}</span>${s.title}</h3><p>${s.body}</p></section>`).join('')}<div class="callout"><strong>Contoh penerapan dalam kehidupan sehari-hari</strong><p>${l.apply}</p></div></article><aside class="lesson-side lesson-summary"><div class="kicker">INTI PEMBELAJARAN</div><h3>${l.name} dalam satu gagasan</h3><p>${l.focus}</p><div class="summary-divider"></div><div class="kicker">TANTANGAN MATERI</div><p>Jawab tiga pertanyaan umpan balik untuk memeriksa pemahamanmu. Jawaban dan pembahasan akan terlihat setelah setiap pilihan.</p><button class="primary full-button" onclick="toggleFeedback()">${feedbackPanelOpen?'Tutup kuis umpan balik':'Mulai kuis umpan balik'} <span aria-hidden="true">→</span></button><p class="step-meta">${Object.keys(answers).length} dari ${l.feedback.length} pertanyaan dijawab</p></aside></div><div class="lesson-actions"><div class="actions-left"><button class="secondary" onclick="go('peta')">← Kembali ke peta</button><button class="secondary" onclick="toggleFeedback()">✎ Kuis &amp; umpan balik <span class="button-count">${Object.keys(answers).length}/3</span></button></div><button class="primary" id="completeLessonBtn" onclick="completeLesson(${activeLesson})" ${done?'':'disabled'}>${activeLesson===lessons.length-1?'Tandai selesai & kembali ke peta':'Tandai selesai & lanjutkan →'}</button></div><p class="step-meta">${done?'Semua pertanyaan sudah dijawab. Kamu dapat menandai materi ini selesai.':'Selesaikan tiga pertanyaan umpan balik untuk mengaktifkan tombol penyelesaian materi.'}</p>${feedbackPanelOpen?`<div class="feedback-backdrop" onclick="toggleFeedback()"></div><aside class="feedback-drawer"><div class="drawer-head"><div><div class="kicker">LATIHAN PER MATERI</div><h2>Kuis &amp; umpan balik</h2><p>${l.name} · ${Object.keys(answers).length} dari 3 dijawab</p></div><button class="drawer-close" onclick="toggleFeedback()" aria-label="Tutup kuis">×</button></div><div class="drawer-content">${feedbackContent}</div><div class="drawer-foot">${done?'<strong>Bagus!</strong> Semua pertanyaan selesai. Tutup panel untuk menandai materi selesai.':'Pilih jawaban pada ketiga pertanyaan untuk melanjutkan.'}</div></aside>`:''}`);}
function toggleFeedback(){feedbackPanelOpen=!feedbackPanelOpen;renderLesson();}
function answerLesson(qi,choice){if(!lessonAnswers[activeLesson])lessonAnswers[activeLesson]={};lessonAnswers[activeLesson][qi]=choice;if(choice===lessons[activeLesson].feedback[qi].a)playCorrect();else playWrong();feedbackPanelOpen=true;renderLesson();}
function completeLesson(i){const answers=lessonAnswers[i]||{};if(Object.keys(answers).length<lessons[i].feedback.length){feedbackPanelOpen=true;renderLesson();return;}completed.add(i);feedbackPanelOpen=false;if(completed.size===lessons.length){showObjective=false;go('peta');}else{activeLesson=i+1;go('level');}}
function openLesson(i){if(i===0||completed.has(i-1)){activeLesson=i;feedbackPanelOpen=false;go('level');}}
function dismissObjective(){showObjective=false;renderMap();}
function nextIntro(){if(introStep<3){introStep++;renderIntro();}}
function enterMap(){visitedMap=true;showObjective=true;go('peta');}
function renderMembers(){surface(`${header('Para penyusun','Disusun bersama untuk menemani perjalanan belajar Darsana.','♧','TIM PENYUSUN')}<div class="member-list">${members.map((m,i)=>`<div class="member"><span class="member-number">${String(i+1).padStart(2,'0')}</span><div class="member-name">${m[0]}<small>Nomor absen ${m[1]}</small></div></div>`).join('')}</div><div class="actions"><button class="secondary" onclick="go('home')">Kembali ke beranda</button><button class="primary" onclick="go('peta')">Lanjut menjelajah →</button></div>`);}
function renderInstructions(){const steps=['Tekan tombol Mulai di halaman beranda.','Klik bubble percakapan untuk melanjutkan pengantar hingga tombol Jelajah Peta muncul.','Baca tujuan pembelajaran pada peta, lalu pilih materi yang terbuka.','Pelajari seluruh isi materi dan jawab tiga pertanyaan kuis umpan balik.','Setelah semua materi selesai, jelajahi infografis, aktivitas interaktif, kuis akhir, refleksi, dan daftar pustaka.','Periksa skor dan pembahasan kuis untuk mengetahui bagian yang sudah dipahami dan yang perlu dipelajari kembali.'];surface(`${header('Cara menggunakan MPI','Ikuti langkah sederhana berikut untuk menikmati perjalanan belajar.','?','PETUNJUK PENGGUNAAN')}<div class="simple-grid">${steps.map((s,i)=>`<article class="info-card"><div class="card-icon">${['▶','☏','⌁','✧','▤','✎'][i]}</div><h3>Langkah ${i+1}</h3><p>${s}</p></article>`).join('')}</div><div class="actions"><button class="primary" onclick="go(visitedMap?'peta':'home')">${visitedMap?'Kembali ke peta':'Kembali ke beranda'} →</button></div>`);}
function renderInfographic(){surface(`${header('Sad Darsana dalam sekilas','Poster ringkas untuk mengingat fokus utama enam aliran filsafat Hindu.','▥','INFOGRAFIS')}<div class="poster"><div class="poster-hero"><div><div class="kicker" style="color:#d5dfbd">PETA GAGASAN</div><h2>Enam cara memandang kehidupan</h2><p>Darsana berasal dari kata dṛś, yang berarti “melihat” atau “memandang”. Sad Darsana memuat enam aliran dengan fokus pemikiran yang berbeda.</p></div><div class="poster-stamp" aria-hidden="true">✦</div></div>${lessons.map((l,i)=>`<article class="poster-card"><span class="poster-no">ALIRAN 0${i+1}</span><h3>${l.icon} ${l.name}</h3><p><strong>${l.figure}</strong></p><p>${l.focus}</p></article>`).join('')}<div class="poster-foot"><strong>Ingat kata kuncinya:</strong> Nyaya—penalaran · Waiśesika—Padartha · Samkhya—Purusa dan Prakrti · Yoga—Astangga Yoga · Mimamsa—Weda dan Dharma · Wedanta—Brahman dan Atman.</div></div><div class="actions"><button class="secondary" onclick="go('peta')">Kembali ke peta</button><button class="primary" onclick="startQuiz()">Mulai kuis akhir →</button></div>`);}
let mazeMap=['###########','#S..#.....#','#.#...##..#','#...#..K..#','#.D...#...#','#...H..D.E#','###########'];
let mazePlayer={r:1,c:1},mazeLives=3,mazeKeys=0,mazeOpened=new Set(),mazeCollected=new Set(),mazeQuestion=null,mazeOver=false,mazeWon=false,mazeScore=0,mazeWrongFlash=false,mazeFeedback='';
const mazeQuestions=[
 {q:'Dalam konsep utama, Darsana berasal dari urat kata apa?',o:['drs','yuj','vid'],a:0,e:'Kata darsana berasal dari urat kata drs, yang berarti melihat atau mengalami.'},
 {q:'Kelompok Astika mengakui otoritas…',o:['Brhaspati Sutra','Weda','Tripitaka'],a:1,e:'Astika mengakui otoritas Weda sebagai sumber ajaran, secara langsung maupun tidak langsung.'},
 {q:'Manakah yang termasuk kelompok Nastika dalam materi?',o:['Nyaya','Yoga','Jaina'],a:2,e:'Kelompok Nastika dalam materi terdiri dari Carwaka, Jaina, dan Buddha.'},
 {q:'Filsafat Carwaka dikaitkan dengan tokoh…',o:['Brhaspati','Rsi Gautama','Maharsi Patanjali'],a:0,e:'Materi menyebut Carwaka didirikan oleh Brhaspati dan ajarannya tertuang dalam Brhaspati Sutra.'},
 {q:'Menurut materi, tujuan akhir perjalanan hidup dalam filsafat Buddha adalah…',o:['Nirwana','Padartha','Pramana'],a:0,e:'Materi yang kamu berikan menyebut tujuan akhir perjalanan hidup manusia adalah nirwana.'}
];
function startActivity(){mazePlayer={r:1,c:1};mazeLives=3;mazeKeys=0;mazeOpened=new Set();mazeCollected=new Set();mazeQuestion=null;mazeOver=false;mazeWon=false;mazeScore=0;mazeWrongFlash=false;mazeFeedback='';go('aktivitas');}
function mazeCell(r,c){return mazeMap[r]?.[c]||'#';}
function renderActivity(){const icons={'#':'🌳','.':'','S':'🧭','D':'🚪','H':'💚','E':'🏆','K':'🗝️'};const grid=mazeMap.map((row,r)=>[...row].map((cell,c)=>{const key=`${r}-${c}`,isPlayer=mazePlayer.r===r&&mazePlayer.c===c;let cls=cell==='#'?'maze-wall':'maze-path';if(cell==='D'&&!mazeOpened.has(key))cls+=' maze-door';if(cell==='D'&&mazeOpened.has(key))cls+=' maze-path';if(cell==='H'&&mazeCollected.has(key))cls+=' maze-path';if(cell==='K'&&mazeCollected.has(key))cls+=' maze-path';if(cell==='E')cls+=' maze-exit';return `<div class="${cls}" aria-label="${isPlayer?'Pemain':cell==='D'&&!mazeOpened.has(key)?'Pintu soal':cell==='H'?'Bonus nyawa':cell==='K'?'Kunci':cell==='E'?'Gerbang akhir':''}">${isPlayer?'<span class="maze-player">🧑🏻‍🎓</span>':cell==='D'&&!mazeOpened.has(key)?'🔒':cell==='H'&&!mazeCollected.has(key)?'💚':cell==='K'&&!mazeCollected.has(key)?'🗝️':cell==='E'?'🏁':cell==='#'?'🌿':''}</div>`}).join('')).join('');let overlay='';if(mazeQuestion!==null&&!mazeOver&&!mazeWon){const q=mazeQuestions[mazeQuestion.qi];overlay=`<div class="maze-modal"><div class="maze-modal-card"><span class="maze-tag">PINTU TANTANGAN</span><h2>${q.q}</h2><div class="maze-options">${q.o.map((o,i)=>`<button class="maze-answer" onclick="answerMaze(${i})">${String.fromCharCode(65+i)}. ${o}</button>`).join('')}</div>${mazeFeedback?`<p class="maze-feedback">${mazeFeedback}</p>`:''}<p class="maze-hint">Jawaban salah mengurangi satu nyawa. Kamu masih bisa mencoba lagi selama nyawa tersedia.</p><button class="secondary" onclick="closeMazeQuestion()">Tutup dulu</button></div></div>`;}else if(mazeOver){overlay=`<div class="maze-modal"><div class="maze-modal-card maze-end"><div class="maze-end-icon">💤</div><h2>Nyawa habis!</h2><p>Jangan menyerah. Baca kembali konsep utama, lalu coba labirin sekali lagi.</p><button class="primary" onclick="startActivity()">Main lagi ↻</button><button class="secondary" onclick="go('konsep')">Baca konsep utama</button></div></div>`;}else if(mazeWon){overlay=`<div class="maze-modal"><div class="maze-modal-card maze-end"><div class="maze-end-icon">🏆</div><h2>Gerbang kebijaksanaan terbuka!</h2><p>Kamu berhasil menyelesaikan labirin. Skor: <strong>${mazeScore}</strong> poin · Kunci: ${mazeKeys} · Nyawa tersisa: ${mazeLives}.</p><button class="primary" onclick="startActivity()">Main lagi ↻</button><button class="secondary" onclick="go('peta')">Kembali ke peta</button></div></div>`;}surface(`${header('Labirin Kebijaksanaan','Jelajahi lorong, buka pintu dengan menjawab soal, dan temukan gerbang akhir.','🗝️','AKTIVITAS INTERAKTIF')}${mazeFeedback&&mazeQuestion===null&&!mazeOver&&!mazeWon?`<div class="maze-notice">${mazeFeedback}</div>`:''}<div class="maze-hud"><span>❤️ ${'❤️'.repeat(mazeLives)}${'🖤'.repeat(3-mazeLives)}</span><span>🗝️ ${mazeKeys}/1</span><span>⭐ ${mazeScore} poin</span></div><div class="maze-layout"><div class="maze-board-wrap"><div class="maze-board" style="--maze-cols:11">${grid}</div><div class="maze-legend"><span>🔒 Pintu soal</span><span>💚 Bonus nyawa</span><span>🗝️ Kunci</span><span>🏁 Gerbang akhir</span></div></div><aside class="maze-side"><div class="maze-side-icon">🧭</div><h2>Petunjuk ekspedisi</h2><p>Gunakan tombol arah untuk bergerak. Saat tiba di pintu, jawab pertanyaan untuk membukanya. Kumpulkan kunci sebelum menuju gerbang akhir.</p><div class="maze-controls"><button onclick="moveMaze(-1,0)" aria-label="Atas">▲</button><div><button onclick="moveMaze(0,-1)" aria-label="Kiri">◀</button><button onclick="moveMaze(1,0)" aria-label="Bawah">▼</button><button onclick="moveMaze(0,1)" aria-label="Kanan">▶</button></div></div><p class="maze-small">Bisa juga gunakan tombol panah pada keyboard komputer.</p><button class="secondary full-button" onclick="startActivity()">Mulai ulang</button></aside></div><div class="actions"><button class="secondary" onclick="go('home')">Kembali ke beranda</button><button class="primary" onclick="go('konsep')">Baca konsep utama →</button></div>${overlay}`);}
function closeMazeQuestion(){mazeQuestion=null;renderActivity();}
function answerMaze(choice){if(mazeQuestion===null)return;const q=mazeQuestions[mazeQuestion.qi];if(choice===q.a){playCorrect();mazeOpened.add(`${mazeQuestion.r}-${mazeQuestion.c}`);mazeScore+=20;mazeQuestion=null;mazeWrongFlash=false;mazeFeedback='';renderActivity();}else{playWrong();mazeLives--;mazeScore=Math.max(0,mazeScore-5);mazeWrongFlash=true;mazeFeedback='Belum tepat. Nyawa berkurang satu. Coba pikirkan kembali konsep yang sudah dipelajari.';if(mazeLives<=0){mazeLives=0;mazeOver=true;mazeQuestion=null;}renderActivity();}}
function moveMaze(dr,dc){if(mazeOver||mazeWon||mazeQuestion!==null)return;const r=mazePlayer.r+dr,c=mazePlayer.c+dc,cell=mazeCell(r,c),key=`${r}-${c}`;if(cell==='#')return;if(cell==='D'&&!mazeOpened.has(key)){let qi=(mazeOpened.size)%mazeQuestions.length;mazeQuestion={r,c,qi};renderActivity();return;}if(cell==='E'&&mazeKeys<1){mazeFeedback='Gerbang masih terkunci. Temukan kunci emas 🗝️ di lorong labirin terlebih dahulu.';renderActivity();return;}mazeFeedback='';mazePlayer={r,c};if(cell==='K'&&!mazeCollected.has(key)){mazeCollected.add(key);mazeKeys++;mazeScore+=10;}if(cell==='H'&&!mazeCollected.has(key)){mazeCollected.add(key);mazeLives=Math.min(3,mazeLives+1);mazeScore+=10;}if(cell==='E'&&mazeKeys>=1){mazeWon=true;mazeScore+=30;}renderActivity();}
window.addEventListener('keydown',e=>{const moves={ArrowUp:[-1,0],ArrowDown:[1,0],ArrowLeft:[0,-1],ArrowRight:[0,1]};if(current==='aktivitas'&&moves[e.key]){e.preventDefault();moveMaze(...moves[e.key]);}});

let pickedWords=[];
function pickWord(w){if(!pickedWords.includes(w)){pickedWords.push(w);const el=$('#wordAnswer');if(el)el.textContent=pickedWords.join(' → ');document.querySelectorAll('.word-chip').forEach(b=>{if(b.textContent===w)b.classList.add('selected');});}}
function clearWord(){pickedWords=[];const el=$('#wordAnswer');if(el)el.textContent='Urutan pilihan akan muncul di sini.';document.querySelectorAll('.word-chip').forEach(b=>b.classList.remove('selected'));}
function isActivityCorrect(a,answer){if(a.type==='match')return a.pairs.every((p,i)=>answer[i]===p[1]);if(a.type==='word')return answer.join('|')===a.answer.join('|');return answer===a.a;}
function recordActivity(answer){if(activityAnswers[activityIndex]!==undefined)return;activityAnswers[activityIndex]=answer;if(isActivityCorrect(activityRun[activityIndex],answer))activityScore++;}
function answerActivity(choice){const a=activityRun[activityIndex];if(a.type==='match'||a.type==='word')return;recordActivity(choice);renderActivity();}
function submitMatch(){const a=activityRun[activityIndex],vals=a.pairs.map((_,i)=>$(`#match-${i}`).value);if(vals.some(v=>!v)){alert('Lengkapi semua pasangan terlebih dahulu.');return;}recordActivity(vals);renderActivity();}
function submitWord(){const a=activityRun[activityIndex];if(pickedWords.length===0){alert('Pilih kata terlebih dahulu.');return;}recordActivity([...pickedWords]);pickedWords=[];renderActivity();}
function nextActivity(){if(activityAnswers[activityIndex]===undefined)return;activityIndex++;pickedWords=[];renderActivity();}
function startQuiz(){quizQuestionsForRun=[...quizQuestions];quizIndex=0;quizAnswers={};quizFinished=false;quizStart=Date.now();go('kuis');startQuizTimer();}
function startQuizTimer(){if(quizTimer)clearInterval(quizTimer);quizTimer=setInterval(()=>{const el=$('#quizClock');if(el){const sec=Math.max(0,600-Math.floor((Date.now()-quizStart)/1000));el.textContent=formatTime(sec);if(sec===0){clearInterval(quizTimer);quizFinished=true;go('hasil');}}},1000);}
function formatTime(sec){return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}
function renderQuiz(){if(quizFinished){go('hasil');return;}const q=quizQuestionsForRun[quizIndex];surface(`${header('Uji pengetahuanmu','Jawab 15 soal pilihan ganda. Waktu pengerjaan tersedia selama 10 menit. Skor dan pembahasan ditampilkan setelah kuis dikumpulkan.','✎','KUIS AKHIR')}<div class="quiz-meta"><span>Soal ${quizIndex+1} dari ${quizQuestionsForRun.length}</span><span>Waktu tersisa: <strong id="quizClock">10:00</strong></span></div><div class="progress-track" style="margin:12px 0 24px"><span style="width:${(quizIndex+1)/quizQuestionsForRun.length*100}%"></span></div><div class="question">${q.q}</div><div class="quiz-options">${q.o.map((x,i)=>`<button class="option ${quizAnswers[quizIndex]===i?'selected':''}" onclick="chooseQuiz(${i})">${String.fromCharCode(65+i)}. ${x}</button>`).join('')}</div><div class="actions"><button class="secondary" onclick="quizIndex=Math.max(0,quizIndex-1);renderQuiz()" ${quizIndex===0?'disabled':''}>← Sebelumnya</button><button class="secondary" onclick="quizIndex=Math.min(quizQuestionsForRun.length-1,quizIndex+1);renderQuiz()" ${quizIndex===quizQuestionsForRun.length-1?'disabled':''}>Berikutnya →</button><button class="primary" onclick="finishQuiz()">Kumpulkan kuis</button></div>`);const el=$('#quizClock');if(el)el.textContent=formatTime(Math.max(0,600-Math.floor((Date.now()-quizStart)/1000)));}
function chooseQuiz(i){quizAnswers[quizIndex]=i;renderQuiz();}
function finishQuiz(){const missing=quizQuestionsForRun.filter((q,i)=>quizAnswers[i]===undefined).length;if(missing&&!confirm(`Masih ada ${missing} soal belum dijawab. Tetap kumpulkan kuis?`))return;quizFinished=true;if(quizTimer)clearInterval(quizTimer);go('hasil');}
function scoreData(){const correct=quizQuestionsForRun.reduce((n,q,i)=>n+(quizAnswers[i]===q.a?1:0),0);return{correct,score:Math.round(correct/quizQuestionsForRun.length*100),answered:Object.keys(quizAnswers).length};}
function renderResult(){const r=scoreData(),elapsed=Math.min(600,Math.floor((Date.now()-quizStart)/1000));const message=r.score>=80?'Hebat! Pemahamanmu sudah kuat.':r.score>=60?'Bagus! Pelajari kembali beberapa konsep untuk meningkatkan hasil.':'Tetap semangat. Baca kembali materi, lalu pelajari pembahasannya.';surface(`${header('Hasil belajarmu','Gunakan skor untuk melihat pemahamanmu terhadap enam aliran Sad Darsana.','✦','HASIL KUIS')}<div class="result-score"><strong>${r.score}</strong><span>skor dari 100</span><p>${message}</p><p class="elapsed">Waktu pengerjaan: ${formatTime(elapsed)}</p></div><div class="result-stats"><div class="result-stat"><strong>${r.correct}</strong><span>Jawaban benar</span></div><div class="result-stat"><strong>${quizQuestionsForRun.length-r.correct}</strong><span>Salah atau kosong</span></div><div class="result-stat"><strong>${r.answered}/${quizQuestionsForRun.length}</strong><span>Terjawab</span></div></div><div class="note">Buka pembahasan untuk melihat jawaban yang tepat beserta alasan setiap soal.</div><div class="actions"><button class="secondary" onclick="go('pembahasan')">Lihat pembahasan</button><button class="quiet-button" onclick="startQuiz()">Ulangi kuis</button><button class="primary" onclick="go('peta')">Kembali ke peta</button></div>`);}
function renderReview(){surface(`${header('Pembahasan jawaban','Periksa alasan dari setiap jawaban agar konsepnya semakin jelas.','☷','UMPAN BALIK KUIS')}<div class="review-list">${quizQuestionsForRun.map((q,i)=>`<article class="review-item"><div class="kicker">SOAL ${i+1} · ${quizAnswers[i]===q.a?'BENAR':'PELAJARI LAGI'}</div><h3>${q.q}</h3><p><strong>Jawabanmu:</strong> ${quizAnswers[i]===undefined?'Belum dijawab':q.o[quizAnswers[i]]}</p><p><strong>Jawaban tepat:</strong> ${q.o[q.a]}</p><p>${q.e}</p></article>`).join('')}</div><div class="actions"><button class="secondary" onclick="go('hasil')">← Kembali ke hasil</button><button class="primary" onclick="go('peta')">Kembali ke peta</button></div>`);}
function renderReflection(){surface(`${header('Ruang refleksi','Tuliskan pemikiranmu setelah menelusuri enam aliran Sad Darsana.','☼','REFLEKSI DIRI')}<div class="reflection-list"><div class="reflection-field"><label for="r1">1. Gagasan Darsana apa yang paling menarik bagimu? Mengapa?</label><textarea id="r1" placeholder="Tuliskan refleksimu di sini…"></textarea></div><div class="reflection-field"><label for="r2">2. Bagaimana kamu dapat menerapkan salah satu gagasan tersebut dalam kehidupan sehari-hari?</label><textarea id="r2" placeholder="Berikan contoh sederhana…"></textarea></div><div class="reflection-field"><label for="r3">3. Apa hal baru yang kamu pahami setelah mempelajari Sad Darsana?</label><textarea id="r3" placeholder="Ceritakan hal yang kamu pelajari…"></textarea></div></div><div class="actions"><button class="secondary" onclick="go('peta')">Kembali ke peta</button><button class="primary" onclick="saveReflection()">Simpan refleksi →</button></div><p class="step-meta">Jawaban tersimpan sementara selama halaman ini terbuka. Salin jawaban jika ingin menyimpannya di tempat lain.</p>`);}
function saveReflection(){reflectionSaved=true;go('refleksi-selesai');}
function renderReflectionDone(){surface(`${header('Terima kasih sudah berefleksi','Kamu telah meluangkan waktu untuk menghubungkan materi dengan pengalaman belajar.','✦','REFLEKSI SELESAI')}<div class="note">Refleksi membantumu menyadari gagasan yang paling berkesan dan cara menerapkannya. Jawaban tidak dikirim ke mana pun.</div><div class="actions"><button class="secondary" onclick="go('refleksi')">Periksa jawaban</button><button class="primary" onclick="go('peta')">Kembali ke peta</button></div>`);}
function renderSources(){surface(`${header('Daftar pustaka','Sumber materi pembelajaran Darsana. Informasi yang belum tersedia tidak ditambahkan agar data bibliografi tidak dibuat-buat.','▤','SUMBER BELAJAR')}<article class="book-entry"><div class="book-icon">📚</div><div><h3>Buku Ajar Darsana</h3><p>Penulis: Ida Bagus Wika Krishna.</p><p>Cetakan pertama, Juni 2022.</p></div></article><article class="book-entry"><div class="book-icon">📖</div><div><h3>Agama Hindu dan Budi Pekerti Untuk Siswa SMA/SMK Kelas XI - Semester Ganjil</h3><p>Ketua penyusun: I Kadek Arta Jaya, S. Ag., M.Pd.H.</p><p>Tahun terbit: 2026.</p></div></article><div class="actions"><button class="primary" onclick="go('peta')">Kembali ke peta</button></div>`);}
function renderConclusion(){surface(`${header('Inti perjalanan','Enam aliran Sad Darsana menawarkan cara pandang yang beragam untuk memahami pengetahuan, realitas, diri, kewajiban, dan pembebasan.','✧','KESIMPULAN')}<div class="simple-grid">${lessons.map(l=>`<article class="info-card"><div class="card-icon">${l.icon}</div><h3>${l.name}</h3><p>${l.focus}</p></article>`).join('')}</div><div class="note">Pelajari setiap gagasan sesuai konteksnya. Penalaran, pengamatan, pengendalian diri, tanggung jawab, dan refleksi dapat menjadi pintu untuk menghubungkan materi dengan pengalaman sehari-hari.</div><div class="actions"><button class="secondary" onclick="go('peta')">Kembali ke peta</button><button class="primary" onclick="startQuiz()">Coba kuis akhir →</button></div>`);}
render();

// Audio lembut dan efek respons; suara dimulai setelah interaksi pertama karena kebijakan browser.
let darsanaAudioContext=null, ambientTimer=null, ambientStarted=false;
function audioContext(){try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return null;if(!darsanaAudioContext)darsanaAudioContext=new AC();if(darsanaAudioContext.state==='suspended')darsanaAudioContext.resume();return darsanaAudioContext;}catch(e){return null;}}
function tone(freq,duration=0.16,type='sine',volume=0.035,delay=0){const ctx=audioContext();if(!ctx)return;const osc=ctx.createOscillator(),gain=ctx.createGain();osc.type=type;osc.frequency.value=freq;gain.gain.setValueAtTime(0.0001,ctx.currentTime+delay);gain.gain.exponentialRampToValueAtTime(volume,ctx.currentTime+delay+0.025);gain.gain.exponentialRampToValueAtTime(0.0001,ctx.currentTime+delay+duration);osc.connect(gain);gain.connect(ctx.destination);osc.start(ctx.currentTime+delay);osc.stop(ctx.currentTime+delay+duration+0.04);}
function playCorrect(){tone(660,.13,'sine',.045);tone(880,.22,'sine',.035,.12);}
function playWrong(){tone(190,.22,'triangle',.045);if('vibrate'in navigator)navigator.vibrate([90,45,90]);}
function startAmbientMusic(){if(ambientStarted)return;const ctx=audioContext();if(!ctx)return;ambientStarted=true;const notes=[261.63,329.63,392,329.63,293.66,349.23,392,349.23];let i=0;const playNote=()=>{if(!ambientStarted)return;const f=notes[i%notes.length];tone(f,1.25,'sine',.006);i++;};playNote();ambientTimer=setInterval(playNote,1750);}
document.addEventListener('pointerdown',startAmbientMusic,{once:true,passive:true});
